<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import type { DetallePeriodoFinanciero, PeriodoFinanciero, PeriodoFinancieroPayload } from '../interfaces/periodo-financiero.interface'
import { cambiarEstadoMesFinanciero, cambiarEstadoPeriodoFinanciero, generarMesesPeriodoFinanciero, guardarPeriodoFinanciero, listarPeriodosFinancieros, obtenerMesesPeriodoFinanciero, obtenerPeriodoFinanciero } from '../services/periodo-financiero'
const rows = ref<PeriodoFinanciero[]>([]), loading = ref(false), error = ref(''), success = ref(''), showForm = ref(false), editing = ref<number | null>(null), detail = ref<PeriodoFinanciero | null>(null)
const form = reactive<PeriodoFinancieroPayload>({ anio: new Date().getFullYear(), descripcion: '' })
const months = ['Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre']
const message = (e: unknown) => e instanceof Error ? e.message : 'No se pudo completar la operación.'
async function load() { loading.value = true; error.value = ''; try { rows.value = await listarPeriodosFinancieros() } catch (e) { error.value = message(e) } finally { loading.value = false } }
function create() { editing.value = null; Object.assign(form, { anio: new Date().getFullYear(), descripcion: '' }); showForm.value = true }
async function edit(item: PeriodoFinanciero) { loading.value = true; try { const value = await obtenerPeriodoFinanciero(item.id); editing.value = value.id; Object.assign(form, { anio: value.anio, descripcion: value.descripcion }); showForm.value = true } catch (e) { error.value = message(e) } finally { loading.value = false } }
async function save() { loading.value = true; error.value = ''; try { await guardarPeriodoFinanciero(editing.value, { ...form }); success.value = `Periodo financiero ${editing.value ? 'actualizado' : 'creado'} correctamente.`; showForm.value = false; await load() } catch (e) { error.value = message(e) } finally { loading.value = false } }
async function toggle(item: PeriodoFinanciero) { const action = item.estado ? 'desactivar' : 'activar'; if (!confirm(`¿Desea ${action} el periodo ${item.anio}?`)) return; loading.value = true; try { await cambiarEstadoPeriodoFinanciero(item.id); success.value = `Periodo ${item.estado ? 'desactivado' : 'activado'} correctamente.`; await load() } catch (e) { error.value = message(e) } finally { loading.value = false } }
async function viewMonths(item: PeriodoFinanciero) { loading.value = true; try { detail.value = await obtenerMesesPeriodoFinanciero(item.id) } catch (e) { error.value = message(e) } finally { loading.value = false } }
async function generateMonths() { if (!detail.value || !confirm(`¿Generar los 12 meses del periodo ${detail.value.anio}?`)) return; loading.value = true; try { await generarMesesPeriodoFinanciero(detail.value.id); success.value = 'Meses generados correctamente.'; await viewMonths(detail.value); await load() } catch (e) { error.value = message(e) } finally { loading.value = false } }
async function changeMonth(item: DetallePeriodoFinanciero, action: 'abrir' | 'cerrar') { if (!confirm(`¿Desea ${action} ${months[item.mes-1]} de ${item.anio}?`)) return; loading.value = true; try { await cambiarEstadoMesFinanciero(item.id, action); success.value = `Mes ${action === 'abrir' ? 'abierto' : 'cerrado'} correctamente.`; if (detail.value) await viewMonths(detail.value); await load() } catch (e) { error.value = message(e) } finally { loading.value = false } }
onMounted(load)
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Administración / Finanzas / Periodos financieros</nav><header class="hero"><div class="mark">PF</div><div><small>MIA · FINANZAS · MAESTROS</small><h1>Periodos financieros</h1><p>Administración de ejercicios y apertura o cierre de sus periodos mensuales.</p></div><strong>{{rows.length}} ejercicios</strong><button @click="create">+ Nuevo periodo</button></header><p v-if="error" class="flash badmsg">{{error}}</p><p v-if="success" class="flash okmsg">{{success}}</p><section class="card"><div v-if="loading&&!rows.length" class="empty">Procesando…</div><div v-else-if="!rows.length" class="empty">No se encontraron periodos financieros.</div><div v-else class="grid"><article v-for="item in rows" :key="item.id" :class="{inactive:!item.estado}"><header><b>{{item.anio}}</b><span :class="item.estado?'good':'bad'">{{item.estado?'ACTIVO':'INACTIVO'}}</span></header><h2>{{item.descripcion}}</h2><div class="exercise"><small>ESTADO DEL EJERCICIO</small><strong :class="item.estado_ejercicio.toLowerCase()">{{item.estado_ejercicio}}</strong><span>{{item.detalles_count||0}} / 12 meses</span></div><footer><button @click="viewMonths(item)">Gestionar meses</button><button class="edit" @click="edit(item)">Editar</button><button :class="item.estado?'danger':'activate'" @click="toggle(item)">{{item.estado?'Desactivar':'Activar'}}</button></footer></article></div></section><div v-if="showForm" class="backdrop" @mousedown.self="showForm=false"><form class="dialog small" @submit.prevent="save"><header><div><small>{{editing?'EDICIÓN':'NUEVO EJERCICIO'}}</small><h2>{{editing?'Editar':'Registrar'}} periodo financiero</h2></div><button type="button" @click="showForm=false">×</button></header><label>Año<input v-model.number="form.anio" type="number" min="2000" max="2100" required></label><label>Descripción<input v-model.trim="form.descripcion" maxlength="45" required placeholder="Ejercicio financiero"></label><footer><button type="button" class="soft" @click="showForm=false">Cancelar</button><button :disabled="loading">Guardar</button></footer></form></div><div v-if="detail" class="backdrop" @mousedown.self="detail=null"><section class="dialog months"><header><div><small>PERIODO FINANCIERO</small><h2>{{detail.anio}} · {{detail.descripcion}}</h2></div><span :class="detail.estado_ejercicio.toLowerCase()">{{detail.estado_ejercicio}}</span><button @click="detail=null">×</button></header><div v-if="!detail.detalles?.length" class="nomonths"><p>Este periodo todavía no tiene meses generados.</p><button @click="generateMonths">Generar los 12 meses</button></div><div v-else class="monthgrid"><article v-for="item in detail.detalles" :key="item.id"><header><b>{{months[item.mes-1]}}</b><span :class="item.estado_periodo.toLowerCase()">{{item.estado_periodo}}</span></header><small>{{item.mes.toString().padStart(2,'0')}} / {{item.anio}}</small><footer><button v-if="item.estado_periodo!=='ABIERTO'" class="activate" @click="changeMonth(item,'abrir')">Abrir</button><button v-if="item.estado_periodo!=='CERRADO'" class="danger" @click="changeMonth(item,'cerrar')">Cerrar</button></footer></article></div></section></div></div></template>
<style scoped>
.page{--a:#176d78;color:#344750}nav{margin-bottom:15px;color:#91a0a5;font-size:.68rem}nav a{color:var(--a)}.hero{display:flex;align-items:center;gap:14px;padding:20px;border-left:5px solid var(--a);border-radius:12px;background:#fff}.mark{width:50px;height:50px;display:grid;place-items:center;border-radius:10px;color:#fff;background:var(--a);font-weight:800}.hero>div:nth-child(2){flex:1}.hero small,.dialog>header small,.exercise small{color:var(--a);font-size:.49rem;font-weight:800}.hero h1{margin:3px 0;font-size:1.3rem}.hero p{margin:0;color:#7c8b91;font-size:.65rem}.hero strong{font-size:.55rem}button{padding:8px 11px;border:0;border-radius:6px;color:#fff;background:var(--a);font-size:.5rem;cursor:pointer}.soft{color:#607078;background:#edf2f3}.flash{padding:10px;border-radius:6px;font-size:.55rem}.badmsg{color:#9b3d48;background:#fdebee}.okmsg{color:#236c50;background:#e8f7ee}.card{margin-top:11px;background:#fff}.grid{padding:13px;display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.grid>article{padding:14px;border:1px solid #dce5e7;border-top:4px solid var(--a);border-radius:8px}.grid>article.inactive{opacity:.7;border-top-color:#9ba6aa}.grid article>header{display:flex;justify-content:space-between}.grid article>header>b{font-size:1rem}.grid h2{font-size:.68rem}.exercise{display:grid;grid-template-columns:1fr auto;gap:5px;padding:9px;background:#f2f6f7}.exercise small{grid-column:1/-1}.exercise span{font-size:.48rem}.grid footer,.monthgrid footer{display:flex;gap:5px;margin-top:12px}.good,.bad,.abierto,.cerrado,.creado{padding:4px 8px;border-radius:10px;font-size:.42rem;font-weight:800}.good,.abierto{color:#267153;background:#e5f7ec}.bad,.cerrado{color:#9d414a;background:#fdebed}.creado{color:#6e6260;background:#eeeae8}.edit{background:#c98a24}.danger{background:#b74b54}.activate{background:#27875f}.empty{padding:50px;text-align:center}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#172b3d88}.dialog{width:min(900px,100%);max-height:92vh;padding:20px;box-sizing:border-box;border-radius:12px;background:#fff;overflow:auto}.dialog.small{width:min(500px,100%)}.dialog>header{display:flex;align-items:start;gap:8px}.dialog>header div{flex:1}.dialog h2{margin:3px 0 15px}.dialog>header button{color:#66757b;background:none;font-size:1.2rem}.dialog label{display:grid;gap:5px;margin:10px 0;font-size:.52rem;font-weight:700}.dialog input{box-sizing:border-box;width:100%;padding:9px;border:1px solid #d5dfe2;border-radius:6px;font-size:.52rem}.dialog>footer{display:flex;justify-content:center;gap:8px}.nomonths{padding:50px;text-align:center;font-size:.55rem}.monthgrid{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.monthgrid article{padding:11px;border:1px solid #dce5e7;border-radius:7px}.monthgrid article header{display:flex;justify-content:space-between}.monthgrid article small{font-size:.45rem}@media(max-width:800px){.grid,.monthgrid{grid-template-columns:repeat(2,1fr)}}@media(max-width:550px){.grid,.monthgrid{grid-template-columns:1fr}.hero{flex-wrap:wrap}.mark{display:none}}
</style>
